import React, { useState, useEffect } from "react";
import axios from "axios";
import toast, { Toaster } from "react-hot-toast";

export default function FeePage() {
  const [admissionNo, setAdmissionNo] = useState("");
  const [overall, setOverall] = useState(null);
  const [summary, setSummary] = useState(null);

  // Load overall fee for new visitors
  useEffect(() => {
    axios.get("http://localhost:5000/api/fees")
      .then(res => { if(res.data.success) setOverall(res.data.data); })
      .catch(() => toast.error("Failed to load overall fee"));
  }, []);

  const fetchFee = async () => {
    if(!admissionNo.trim()) return toast.error("Enter Admission No");
    try {
      const res = await axios.get(`http://localhost:5000/api/fees/student/${admissionNo.trim()}`);
      if(res.data.success) setSummary(res.data.data);
    } catch {
      toast.error("Failed to fetch fee");
      setSummary(null);
    }
  };

  const renderFeeTable = (fee) => (
    <table className="fee-table">
      <thead><tr><th>Particulars</th><th>Amount (₹)</th></tr></thead>
      <tbody>
        {Object.values(fee.items).map(it => (
          <tr key={it.title}><td>{it.title}</td><td>{it.amount}</td></tr>
        ))}
        <tr><td><b>Total</b></td><td><b>₹{fee.total}</b></td></tr>
        {fee.paid !== undefined && (
          <>
            <tr><td>Paid</td><td>₹{fee.paid}</td></tr>
            <tr><td>Remaining</td><td>₹{fee.remaining}</td></tr>
          </>
        )}
      </tbody>
    </table>
  );

  return (
    <div className="fee-page">
      <Toaster />
      <h2>💰 School Fee Structure</h2>

      {/* New visitors */}
      {overall && !summary && (
        <div className="fee-card">
          <h3>Overall Fee Structure ({overall.academicYear})</h3>
          <div dangerouslySetInnerHTML={{ __html: overall.notes }} />
          {renderFeeTable(overall)}
          <p>Enter Admission No to see individual fees.</p>
        </div>
      )}

      <div className="search-box">
        <input type="text" placeholder="Admission No" value={admissionNo} onChange={e => setAdmissionNo(e.target.value)} />
        <button onClick={fetchFee}>Search</button>
      </div>

      {/* Individual student / random demo */}
      {summary && (
        <div className="fee-card">
          <h3>{summary.student.studentName}'s Fee</h3>
          {renderFeeTable(summary.fee)}
        </div>
      )}
    </div>
  );
}








